// The v2 estimator workbook export, shared by the classic page and the
// workflow-mode Component-based page. Clones the sample workbook (base64
// below), fills the Ballpark and Project Roll-up tabs, adds Task Breakdown and
// Score Rationale, and leaves every template formula live so the workbook
// keeps repricing when a human edits a score. The page defines
// XLSX_SOURCE = { rows(), container(row), levels() } before this script, and
// optionally template() (another base64 workbook), system(row) (the
// SYSTEM / MODULE layout, see XLSX_LAYOUTS) and register() (project name,
// assumptions, exclusions); nothing here reads page globals.
const XLSX_FACTORS = ['tech', 'size', 'deps', 'unc', 'risk'];
const XLSX_FACTOR_LABELS = { tech: 'Tech', size: 'Size', deps: 'Deps', unc: 'Unc', risk: 'Risk' };
const XLSX_TEMPLATE = '';
const XLSX_BALLPARK = 'xl/worksheets/sheet2.xml'; // v2 tab 2, the scoring grid
const XLSX_ROLLUP = 'xl/worksheets/sheet5.xml'; // v2 tab 5, the project total
const XLSX_ROW0 = 7; // first scoreable row
const XLSX_SLOTS = 30; // the template wires rows 7-36 and nothing past them
const XLSX_NOTE_ROW = 38; // the blank line under FEATURE SUBTOTAL
// Where the Ballpark tab's columns sit. `feature` is Estimator_v2 as shipped:
// the name in A, scores B-F, the template's formulas G-M (weighted score,
// tier, point estimate, spread, est. low/high, flag), our own columns N-P.
// `system` is the workflow template (workflow-based/assets/estimator-system.xlsx),
// the same sheet with SYSTEM / MODULE inserted as A, so everything sits one
// column right. `text` are the row's text columns (the name last) and
// `texts(row)` their values; `head` is the header cell our own column headers
// copy their style from; `project` is the value cell beside the Project label.
const XLSX_LAYOUTS = {
  feature: { text: ['A'], texts: (f) => [f.name], scores: ['B', 'C', 'D', 'E', 'F'], own: ['N', 'O', 'P'], head: 'M6', project: 'B3' },
  system: {
    text: ['A', 'B'], texts: (f) => [XLSX_SOURCE.system(f), f.name], scores: ['C', 'D', 'E', 'F', 'G'], own: ['O', 'P', 'Q'], head: 'N6', project: 'C3',
  },
};
const XLSX_OWN_LABELS = ['MILESTONE', 'CONTAINER', 'WHY THIS TIER'];
const xlsxLayout = () => (XLSX_SOURCE.system ? XLSX_LAYOUTS.system : XLSX_LAYOUTS.feature);
const XLSX_HEAD_STYLE = 12; // the template's own header xf, for generated tabs

function xmlEsc(s) {
  return String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
}
const fCell = (ref, s, f) => `<c r="${ref}" s="${s}"><f>${xmlEsc(f)}</f></c>`;
const sCell = (ref, s, text) => `<c r="${ref}" s="${s}" t="inlineStr"><is><t>${xmlEsc(text)}</t></is></c>`;
const nCell = (ref, s, v) => `<c r="${ref}" s="${s}"><v>${v}</v></c>`;
const blankCell = (ref, s) => `<c r="${ref}" s="${s}"/>`;

// --- Filling the template in place. Every price on the Ballpark tab is one
// of the template's own formulas, so the export writes only what is its own —
// the name (and system), the scores, our three columns — and rewrites
// no cell it does not own. A cell we never touch cannot lose its formula or
// its style, which is also why no style index is hard-coded below: each
// rewritten cell keeps the `s` the template gave it.
const cellAt = (ref) => new RegExp(`<c r="${ref}"([^>]*?)(?:/>|>.*?</c>)`, 's');
const rowAt = (r) => new RegExp(`<row r="${r}"([^>]*?)(?:/>|>(.*?)</row>)`, 's');
const styleAt = (xml, ref) => /s="(\d+)"/.exec(cellAt(ref).exec(xml)?.[1] ?? '')?.[1] ?? '0';

// make(style) → the replacement cell. Spliced by index rather than through
// String.replace, so a `$&` in a feature name is never read as a
// backreference — and a ref the template does not carry throws instead of
// silently writing nothing, which would empty a row and pass every test.
function setCell(xml, ref, make) {
  const m = cellAt(ref).exec(xml);
  if (!m) throw new Error(`the workbook template has no cell ${ref}`);
  return xml.slice(0, m.index) + make(/s="(\d+)"/.exec(m[1])?.[1] ?? '0') + xml.slice(m.index + m[0].length);
}

function appendCells(xml, r, cells) {
  const m = rowAt(r).exec(xml);
  if (!m) throw new Error(`the workbook template has no row ${r}`);
  return `${xml.slice(0, m.index)}<row r="${r}"${m[1]}>${m[2] ?? ''}${cells}</row>${xml.slice(m.index + m[0].length)}`;
}

function fillScores(xml, f, r) {
  return xlsxLayout().scores.reduce((acc, col, i) => setCell(acc, col + r, (s) => (f.scores
    ? nCell(col + r, s, f.scores[XLSX_FACTORS[i]].n) : blankCell(col + r, s))), xml);
}

function fillFeatureRow(xml, f, r) {
  const { text, texts } = xlsxLayout();
  const named = texts(f).reduce((acc, v, i) => setCell(acc, text[i] + r, (s) => sCell(text[i] + r, s, v)), xml);
  const scored = fillScores(named, f, r);
  const style = styleAt(scored, text.at(-1) + r); // the name cell's look
  const own = [f.milestone ?? '', XLSX_SOURCE.container(f), f.scoreNote ?? ''];
  return appendCells(scored, r, xlsxLayout().own.map((col, i) => sCell(col + r, style, own[i])).join(''));
}

// The template ships five worked sample features in rows 7-11; any slot our
// rows do not reach has to be emptied or the sample prices itself alongside
// ours. Emptying keeps the cell — and so its formula neighbours — in place.
function clearRow(xml, r) {
  const { text, scores } = xlsxLayout();
  return [...text, ...scores].reduce(
    (acc, col) => setCell(acc, col + r, (s) => blankCell(col + r, s)), xml);
}

// Patching in place caps the tab at the rows the template wired. Say so in
// the sheet: a silently truncated FEATURE SUBTOTAL is a wrong price.
function overflowNote(xml, dropped) {
  if (!dropped.length) return xml;
  const ref = `A${XLSX_NOTE_ROW}`;
  const text = `${dropped.length} more features did not fit this sheet's ${XLSX_SLOTS} scored rows`
    + ` and are NOT in the subtotal above: ${dropped.map((f) => f.name).join('; ')}.`
    + ' They are listed in full on the Task Breakdown and Score Rationale tabs.';
  return appendCells(xml, XLSX_NOTE_ROW, sCell(ref, styleAt(xml, 'A37'), text));
}

function fillProject(xml) {
  const { project } = XLSX_SOURCE.register?.() ?? {};
  const ref = xlsxLayout().project;
  return project ? setCell(xml, ref, (s) => sCell(ref, s, project)) : xml;
}

function buildBallpark(xml, rows) {
  const shown = rows.slice(0, XLSX_SLOTS);
  const { own, head } = xlsxLayout();
  const headed = appendCells(xml, 6, own.map((col, i) => sCell(`${col}6`, styleAt(xml, head), XLSX_OWN_LABELS[i])).join(''));
  const filled = shown.reduce((acc, f, i) => fillFeatureRow(acc, f, XLSX_ROW0 + i), fillProject(headed));
  const spares = Array.from({ length: XLSX_SLOTS - shown.length }, (_, i) => XLSX_ROW0 + shown.length + i);
  return overflowNote(spares.reduce(clearRow, filled), rows.slice(XLSX_SLOTS));
}

// --- Project Roll-up rows 11-15, in the order the sheet prints them, which
// is not alphabetical. The cells are plain numbers a human can overwrite;
// every multiplier beside them stays a live INDEX formula, so an edited level
// reprices the project inside the workbook.
const ROLLUP_ROWS = ['codebaseMaturity', 'stackFamiliarity', 'specQuality', 'compliance', 'clientDecisions'];

function fillRollup(xml, levels) {
  return ROLLUP_ROWS.reduce((acc, key, i) => {
    const ref = `C${11 + i}`;
    const level = levels?.[key];
    return Number.isInteger(level) ? setCell(acc, ref, (s) => nCell(ref, s, level)) : acc;
  }, xml);
}

// The whole tab hangs off one cell: C6 pulls the Ballpark subtotal and C20
// multiplies it, so every figure below inherits whatever is wrong with it —
// in silence. Two things can be wrong, and both have to be said here, beside
// the number, not only on the tab the number came from.
function rollupWarnings(rows) {
  const out = [];
  const unscored = rows.filter((f) => !f.scores).length;
  const dropped = Math.max(0, rows.length - XLSX_SLOTS);
  if (unscored) {
    out.push(`NOT A PRICE: ${unscored} of ${rows.length} features carry no scores, so the`
      + ' subtotal beside this note and every figure below it read 0. Zero is what an'
      + ' unscored feature weighs here, not what it costs. Score the features on the'
      + ' Ballpark tab and every figure on this sheet prices itself.');
  }
  if (dropped) {
    out.push(`INCOMPLETE: ${dropped} features did not fit the Ballpark tab's ${XLSX_SLOTS}`
      + ' scored rows, so the subtotal beside this note excludes them.');
  }
  return out;
}

// Roll-up sections 7 and 8: fixed merged rows B:F carrying the template's
// sample text. Ours replace it; unused slots are emptied. The rows below hold
// sign-off cells, so none are inserted: the last slot takes whatever is left.
const XLSX_REGISTER = { assumptions: { first: 61, slots: 7 }, exclusions: { first: 70, slots: 9 } };

function fitSlots(items, slots) {
  if (items.length <= slots) return items;
  return [...items.slice(0, slots - 1), `Also: ${items.slice(slots - 1).join('; ')}`];
}

function fillRegister(xml, items, { first, slots }) {
  const fitted = fitSlots(items, slots);
  return Array.from({ length: slots }, (_, i) => `B${first + i}`).reduce((acc, ref, i) => setCell(acc, ref,
    (s) => (i < fitted.length ? sCell(ref, s, fitted[i]) : blankCell(ref, s))), xml);
}

function buildRollup(xml, rows) {
  const warnings = rollupWarnings(rows);
  const noted = warnings.length
    ? appendCells(xml, 6, sCell('D6', styleAt(xml, 'D5'), warnings.join(' ')))
    : xml;
  const reg = XLSX_SOURCE.register?.();
  const leveled = fillRollup(noted, XLSX_SOURCE.levels());
  return reg ? Object.entries(XLSX_REGISTER).reduce((acc, [key, at]) => fillRegister(acc, reg[key], at), leveled) : leveled;
}

// --- Task Breakdown tab: one row per task of every exported feature, for
// reference next to the scoring tab. Filter, sort, and search all come from
// the autofilter dropdowns; the header row is frozen so they survive scrolling.
const TASK_HEADERS = ['FEATURE', 'TASK', 'CATEGORY', 'OPTIMISTIC (H)', 'MOST LIKELY (H)',
  'PESSIMISTIC (H)', 'EXPECTED (PERT)', 'CONFIDENCE', 'ASSUMPTIONS', 'MILESTONE', 'CONTAINER'];

function taskRowXml(f, t, r) {
  const texts = { A: f.name, B: t.name, C: t.category, H: t.confidence,
    I: t.assumptions.join('; '), J: f.milestone ?? '', K: XLSX_SOURCE.container(f) };
  return `<row r="${r}">` + Object.entries(texts).slice(0, 3).map(([c, v]) => sCell(c + r, 0, v)).join('')
    + [t.o, t.m, t.p].map((v, i) => nCell('DEF'[i] + r, 0, v)).join('')
    + fCell(`G${r}`, 0, `(D${r}+4*E${r}+F${r})/6`)
    + Object.entries(texts).slice(3).map(([c, v]) => sCell(c + r, 0, v)).join('') + '</row>';
}

// A generated tab: frozen header row, autofilter over the data, nothing else.
function sheetXml({ headers, body, last }) {
  const head = `<row r="1">${headers.map((h, i) =>
    sCell(String.fromCharCode(65 + i) + 1, XLSX_HEAD_STYLE, h)).join('')}</row>`;
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
    + '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
    + '<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" '
    + 'activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>'
    + `<sheetData>${head}${body}</sheetData><autoFilter ref="A1:${String.fromCharCode(64 + headers.length)}${last}"/></worksheet>`;
}

function buildTaskSheet(rows) {
  const body = rows.flatMap((f) => f.tasks.map((t) => [f, t]))
    .map(([f, t], i) => taskRowXml(f, t, i + 2)).join('');
  const last = 1 + rows.reduce((s, f) => s + f.tasks.length, 0);
  return sheetXml({ headers: TASK_HEADERS, body, last });
}

// --- Score Rationale tab: one row per feature × factor — the engineer's
// view of why each score is what it is (Sheet 1's column N is the sales one).
// Two source columns, because `provenance` and `scoreProvenance` answer
// different questions about different people: did the client ask for this
// feature, and did a reviewer override the agent's score. They share the
// vocabulary `stated`/`proposed`, which read side by side looks like the same
// column disagreeing with itself — so the score's half is spelled out in the
// words it actually means, while the feature's half keeps the page's wording.
const RATIONALE_HEADERS = ['FEATURE', 'FACTOR', 'SCORE', 'ANCHOR', 'EVIDENCE',
  'FEATURE SOURCE', 'SCORE ORIGIN'];
const SCORE_ORIGIN = { proposed: 'agent proposed', stated: 'reviewer changed' };

function rationaleRowXml(f, key, r) {
  const s = f.scores[key];
  return `<row r="${r}">` + sCell(`A${r}`, 0, f.name) + sCell(`B${r}`, 0, XLSX_FACTOR_LABELS[key]) + nCell(`C${r}`, 0, s.n)
    + sCell(`D${r}`, 0, s.anchor) + sCell(`E${r}`, 0, s.cite) + sCell(`F${r}`, 0, f.provenance)
    + sCell(`G${r}`, 0, SCORE_ORIGIN[f.scoreProvenance] ?? '') + '</row>';
}

function buildRationaleSheet(rows) {
  const scored = rows.filter((f) => f.scores);
  const body = scored.flatMap((f) => XLSX_FACTORS.map((k) => [f, k]))
    .map(([f, k], i) => rationaleRowXml(f, k, i + 2)).join('');
  return sheetXml({ headers: RATIONALE_HEADERS, body, last: 1 + scored.length * XLSX_FACTORS.length });
}

// The template owns sheet1-5 and sheetId 1-5; ours land past both.
const EXTRA_SHEETS = [
  { file: 'sheet6.xml', name: 'Task Breakdown', id: 100, rid: 'rIdTasks', build: buildTaskSheet },
  { file: 'sheet7.xml', name: 'Score Rationale', id: 101, rid: 'rIdScores', build: buildRationaleSheet },
];

// Registers a generated sheet in the three package indexes the clone lacks.
function registerSheet(files, enc, sheet) {
  const patch = (path, find, add) => files.set(path,
    enc.encode(new TextDecoder().decode(files.get(path)).replace(find, add + find)));
  patch('xl/workbook.xml', '</sheets>',
    `<sheet state="visible" name="${sheet.name}" sheetId="${sheet.id}" r:id="${sheet.rid}"/>`);
  patch('xl/_rels/workbook.xml.rels', '</Relationships>',
    `<Relationship Id="${sheet.rid}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/${sheet.file}"/>`);
  patch('[Content_Types].xml', '</Types>',
    `<Override PartName="/xl/worksheets/${sheet.file}" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`);
}

// The template ships a cached result beside every formula, computed from the
// sample's own scores. A reader that trusts the cache would open a workbook
// carrying our scores and the sample's prices — the flag asks for a full
// recalculation, and dropping the caches means there is nothing else to show
// if the reader ignores it. Tested: LibreOffice ignores the flag.
const recalcOnLoad = (xml) => xml.replace(/<calcPr[^>]*\/>/, '<calcPr calcId="0" fullCalcOnLoad="1"/>');

const dropCachedValues = (xml) => xml.replace(
  /<c ([^>]*?)>(<f[^>]*\/>|<f[^>]*>[\s\S]*?<\/f>)<v>[\s\S]*?<\/v><\/c>/g,
  (_, attrs, f) => `<c ${attrs.replace(/ t="\w+"/, '')}>${f}</c>`);

// The template's five tabs; ours are generated and carry no stale cache.
const XLSX_TEMPLATE_SHEETS = [1, 2, 3, 4, 5].map((n) => `xl/worksheets/sheet${n}.xml`);

// --- minimal zip: read the deflated template, write a stored archive ---
function b64Bytes(b64) {
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}
function bytesB64(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(s);
}
async function inflateRaw(bytes) {
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}
function zipEocd(bytes, v) {
  for (let i = bytes.length - 22; i >= 0; i--) if (v.getUint32(i, true) === 0x06054b50) return i;
  throw new Error('embedded workbook is not a zip');
}
async function zipEntry(bytes, v, cd) {
  const csize = v.getUint32(cd + 20, true);
  const local = v.getUint32(cd + 42, true);
  const start = local + 30 + v.getUint16(local + 26, true) + v.getUint16(local + 28, true);
  const raw = bytes.subarray(start, start + csize);
  return v.getUint16(cd + 10, true) === 0 ? raw : inflateRaw(raw);
}
async function unzip(bytes) {
  const v = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const files = new Map();
  let cd = v.getUint32(zipEocd(bytes, v) + 16, true);
  while (v.getUint32(cd, true) === 0x02014b50) {
    const nameLen = v.getUint16(cd + 28, true);
    const skip = v.getUint16(cd + 30, true) + v.getUint16(cd + 32, true);
    files.set(new TextDecoder().decode(bytes.subarray(cd + 46, cd + 46 + nameLen)), await zipEntry(bytes, v, cd));
    cd += 46 + nameLen + skip;
  }
  return files;
}

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(bytes) {
  let c = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

// entry: { name: Uint8Array, data: Uint8Array, crc, offset }
function zipHeader(entry, central) {
  const b = new Uint8Array(central ? 46 : 30);
  const v = new DataView(b.buffer);
  v.setUint32(0, central ? 0x02014b50 : 0x04034b50, true);
  const at = central ? 6 : 4; // version-needed field; central adds version-made-by first
  v.setUint16(at, 20, true);
  v.setUint32(at + 10, entry.crc, true);
  v.setUint32(at + 14, entry.data.length, true);
  v.setUint32(at + 18, entry.data.length, true);
  v.setUint16(at + 22, entry.name.length, true);
  if (central) v.setUint32(42, entry.offset, true);
  return b;
}
function zipEnd(count, cdSize, cdStart) {
  const b = new Uint8Array(22);
  const v = new DataView(b.buffer);
  v.setUint32(0, 0x06054b50, true);
  v.setUint16(8, count, true);
  v.setUint16(10, count, true);
  v.setUint32(12, cdSize, true);
  v.setUint32(16, cdStart, true);
  return b;
}
function zipStore(files) {
  const enc = new TextEncoder();
  const chunks = [];
  const centrals = [];
  let offset = 0;
  for (const [path, data] of files) {
    const entry = { name: enc.encode(path), data, crc: crc32(data), offset };
    chunks.push(zipHeader(entry, false), entry.name, data);
    centrals.push(zipHeader(entry, true), entry.name);
    offset += 30 + entry.name.length + data.length;
  }
  const cdSize = centrals.reduce((s, b) => s + b.length, 0);
  const all = [...chunks, ...centrals, zipEnd(files.size, cdSize, offset)];
  const out = new Uint8Array(all.reduce((s, b) => s + b.length, 0));
  all.reduce((at, b) => (out.set(b, at), at + b.length), 0);
  return out;
}

const fillPart = (files, part, fill) => files.set(part,
  new TextEncoder().encode(fill(new TextDecoder().decode(files.get(part)))));

async function buildWorkbook() {
  const files = await unzip(b64Bytes(XLSX_SOURCE.template?.() ?? XLSX_TEMPLATE));
  const enc = new TextEncoder();
  const rows = XLSX_SOURCE.rows();
  fillPart(files, XLSX_BALLPARK, (xml) => buildBallpark(xml, rows));
  fillPart(files, XLSX_ROLLUP, (xml) => buildRollup(xml, rows));
  for (const sheet of EXTRA_SHEETS) {
    files.set(`xl/worksheets/${sheet.file}`, enc.encode(sheet.build(rows)));
    registerSheet(files, enc, sheet);
  }
  for (const part of XLSX_TEMPLATE_SHEETS) fillPart(files, part, dropCachedValues);
  fillPart(files, 'xl/workbook.xml', recalcOnLoad);
  return zipStore(files);
}
window.__buildWorkbook = async () => bytesB64(await buildWorkbook());
window.__downloadXlsx = async () => {
  const blob = new Blob([await buildWorkbook()],
    { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'feature-cost-estimate.xlsx';
  a.click();
  URL.revokeObjectURL(a.href);
};
